/*__CORE__*/

// Default birthday used for Life Path and Personal Year/Month. Set
// BIRTHDAY=YYYY-MM-DD when building, or put it in uebersicht/birthday.txt
// (gitignored). MM-DD still works for personal cycles, but Life Path needs the
// year. The in-widget form stores an override in localStorage.
const BIRTHDAY = __BIRTHDAY__;

const BIRTHDAY_KEY = 'daily-energy-birthday';

const readStoredBirthday = () => {
  try {
    return localStorage.getItem(BIRTHDAY_KEY);
  } catch {
    return null;
  }
};

/** Accept YYYY-MM-DD or legacy MM-DD. Full dates are normalized and padded. */
const normalizeBirthday = (value) => {
  const trimmed = String(value).trim();
  if (/^\d{4}-\d{1,2}-\d{1,2}$/.test(trimmed)) {
    const { year, month, day } = NumerologyCore.parseBirthDateInput(trimmed);
    return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  }
  const { month, day } = NumerologyCore.parseBirthdayInput(trimmed);
  return `${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

/** The in-widget form requires the full date so Life Path always works. */
const normalizeFullBirthday = (value) => {
  const { year, month, day } = NumerologyCore.parseBirthDateInput(String(value).trim());
  return `${year}-${String(month).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
};

const formatBirthday = (value) => normalizeBirthday(value);

const initialBirthday = (() => {
  const value = readStoredBirthday() || BIRTHDAY;
  if (!value) return null;
  try {
    return normalizeBirthday(value);
  } catch {
    return null;
  }
})();

const SELECTED_KEY = 'daily-energy-selected-person';

const readSelected = () => {
  try {
    return localStorage.getItem(SELECTED_KEY);
  } catch {
    return null;
  }
};

const writeSelected = (id) => {
  try {
    if (id) localStorage.setItem(SELECTED_KEY, id);
    else localStorage.removeItem(SELECTED_KEY);
  } catch {
    // Private mode or a locked store: selection just won't persist.
  }
};

/**
 * The command prints the CLI's `roster --json` payload. If that fails (no
 * people file, node moved, CLI missing) it prints nothing and we fall back to
 * the single-birthday behaviour above. Birthdays are read at runtime and never
 * baked into this file.
 */
const cycleOf = (person, key) => {
  const cycles = person && person.cycles;
  if (!cycles) return '\u2014';
  const value = cycles[key];
  return value === undefined || value === null || value === '' ? '\u2014' : value;
};

const parseRoster = (output) => {
  try {
    const parsed = JSON.parse(String(output || ''));
    if (parsed && parsed.ok && Array.isArray(parsed.people)) return parsed;
  } catch {
    // Not JSON: older builds printed an epoch.
  }
  return null;
};

const dateFromOutput = (output) => {
  const roster = parseRoster(output);
  if (roster && /^\d{4}-\d{2}-\d{2}$/.test(String(roster.date || ''))) {
    return new Date(`${roster.date}T12:00:00`);
  }
  const seconds = parseInt(output, 10);
  return Number.isFinite(seconds) ? new Date(seconds * 1000) : new Date();
};

const firstOfMonthKey = (date) =>
  `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}-01`;

const shiftMonthKey = (key, delta) => {
  const base = key ? new Date(`${key}T00:00:00`) : new Date();
  if (Number.isNaN(base.getTime())) return firstOfMonthKey(new Date());
  return firstOfMonthKey(new Date(base.getFullYear(), base.getMonth() + delta, 1));
};

