export const initialState = {
  output: '',
  error: null,
  selectedId: readSelected(),
  birthday: initialBirthday,
  calendarMonth: null,
  editing: false,
  draft: '',
  formError: null
};

export const updateState = (event, previousState) => {
  switch (event.type) {
    case 'SELECT_PERSON': {
      const id = typeof event.id === 'string' ? event.id : null;
      writeSelected(id);
      return { ...previousState, selectedId: id, editing: false, draft: '', formError: null };
    }
    case 'BIRTHDAY_EDIT':
      return {
        ...previousState,
        editing: true,
        draft: previousState.birthday || '',
        formError: null
      };
    case 'BIRTHDAY_DRAFT':
      return { ...previousState, draft: event.value, formError: null };
    case 'BIRTHDAY_CANCEL':
      return { ...previousState, editing: false, draft: '', formError: null };
    case 'BIRTHDAY_SAVE': {
      const value = String(event.value ?? previousState.draft ?? '').trim();

      if (!value) {
        return {
          ...previousState,
          formError: 'Use YYYY-MM-DD, for example 2003-05-23'
        };
      }

      try {
        const normalized = normalizeFullBirthday(value);
        try {
          localStorage.setItem(BIRTHDAY_KEY, normalized);
        } catch {
          // Keep the in-memory value even if persistence is unavailable.
        }
        return {
          ...previousState,
          birthday: normalized,
          editing: false,
          draft: '',
          formError: null
        };
      } catch {
        return {
          ...previousState,
          formError: 'Use YYYY-MM-DD, for example 2003-05-23'
        };
      }
    }
    case 'CALENDAR_SHIFT': {
      const delta = Number(event.delta);
      if (!Number.isFinite(delta) || delta === 0) return previousState;

      const baseKey =
        previousState.calendarMonth ||
        firstOfMonthKey(dateFromOutput(previousState.output));

      return {
        ...previousState,
        calendarMonth: shiftMonthKey(baseKey, delta)
      };
    }
    case 'CALENDAR_TODAY':
      return { ...previousState, calendarMonth: null };
    default: {
      if (event.error) {
        return { ...previousState, error: event.error };
      }

      const nextOutput =
        event.output !== undefined ? event.output : previousState.output;
      const previousCurrentMonth = firstOfMonthKey(dateFromOutput(previousState.output));
      const nextCurrentMonth = firstOfMonthKey(dateFromOutput(nextOutput));
      const calendarMonth =
        previousState.calendarMonth === previousCurrentMonth &&
        previousCurrentMonth !== nextCurrentMonth
          ? null
          : previousState.calendarMonth;

      return {
        ...previousState,
        output: nextOutput,
        error: null,
        calendarMonth
      };
    }
  }
};

