export const render = (
  { output, error, birthday, selectedId, calendarMonth, editing, draft, formError: birthdayError },
  dispatch
) => {
  if (error) {
    return (
      <div style={card}>
        <div style={{ ...title, color: '#d97a2b' }}>Daily Energy</div>
        <div style={{ ...note, marginTop: '10px' }}>{String(error)}</div>
      </div>
    );
  }

  const seconds = parseInt(output, 10);
  const now = Number.isFinite(seconds) ? new Date(seconds * 1000) : new Date();
  const energies = NumerologyCore.calculateNumerologyEnergies(now);
  const todayKey = NumerologyCore.formatDateKey(now);
  const month = NumerologyCore.generateMonthlyCalendar(calendarMonth || todayKey);
  const isCurrentMonth =
    month.year === now.getFullYear() && month.month === now.getMonth();
  const weekdayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  // People come from the CLI at runtime (data/people.json). Primary first, and
  // the primary is the default view when nothing has been picked.
  const roster = parseRoster(output);
  const people = roster && roster.people.length ? roster.people : null;
  const picked = people && selectedId ? people.find((person) => person.id === selectedId) : null;
  const active = picked || (people ? people[0] : null);
  const activeBirthday = active ? active.birthdate : birthday;
  const showRoster = Boolean(people);
  const cycles = NumerologyCore.calculateCycleEnergies(todayKey, activeBirthday || null);

  const lifePath = (() => {
    if (!activeBirthday) return null;
    try {
      return NumerologyCore.calculateLifePath(activeBirthday);
    } catch {
      return null;
    }
  })();
  const lifePathStatus = lifePath
    ? lifePath.summary
    : activeBirthday
      ? 'Add birth year'
      : 'Set birthday';
  const lifePathDetail = lifePath
    ? lifePath.isWealth
      ? '28 · 1 underneath'
      : lifePath.reducedNumber === 33
        ? '33 · 6 underneath'
        : lifePath.total === lifePath.reducedNumber
          ? `${lifePath.total} · master number`
          : `${lifePath.monthValue} + ${lifePath.dayValue} + ${lifePath.yearValue} = ${lifePath.total} → ${lifePath.displayValue}`
    : activeBirthday
      ? 'Life Path needs the full date'
      : 'Full birth date unlocks it';

  return (
    <div style={card}>
      <div style={header}>
        <div style={{ display: 'flex', alignItems: 'baseline', gap: '7px' }}>
          <span style={{ color: GOLD, fontSize: '13px', lineHeight: '1' }}>✦</span>
          <h1 style={title}>Daily Energy</h1>
        </div>
        <div style={dateLine}>
          {now.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' })}
        </div>
      </div>

      {showRoster ? (
        <div style={rosterPanel}>
          <div style={{ ...label, marginBottom: '5px' }}>
            People
            <span style={rosterHint}>data/people.json</span>
          </div>
          {people.map((person) => {
            const isActive = active ? person.id === active.id : false;
            return (
              <button
                key={person.id}
                type="button"
                style={isActive ? rosterRowActive : rosterRow}
                title={
                  person.zodiac && person.zodiac.display
                    ? `${person.name} · ${person.zodiac.display} · Life Path ${person.life_path}`
                    : `${person.name} · Life Path ${person.life_path}`
                }
                onClick={() => dispatch({ type: 'SELECT_PERSON', id: person.id })}
              >
                <span style={rosterName}>
                  {person.name}
                  {person.primary ? <span style={rosterBadge}>primary</span> : null}
                </span>
                <span style={rosterMeta}>
                  LP {person.life_path} · PY {cycleOf(person, 'personal_year')} · PM{' '}
                  {cycleOf(person, 'personal_month')}
                </span>
              </button>
            );
          })}
        </div>
      ) : null}

      <div style={lifePathRow} title={lifePath ? lifePath.calculationNote : undefined}>
        <div>
          <div style={label}>Life Path</div>
          <div style={{ display: 'flex', alignItems: 'baseline' }}>
            <span style={lifePathValue}>{lifePath ? lifePath.displayValue : '—'}</span>
            <span style={lifePathSummary}>{lifePathStatus}</span>
          </div>
        </div>
        <div style={lifePathNote}>{lifePathDetail}</div>
      </div>

      <div style={energyRow}>
        <div>
          <div style={label}>Primary</div>
          <div style={primaryValue}>{energies.fullDateEnergy.displayValue}</div>
          <div style={note}>{energies.fullDateEnergy.summary}</div>
        </div>
        <div>
          <div style={label}>Secondary</div>
          <div style={secondaryValue}>{energies.secondaryEnergy.displayValue}</div>
          <div style={note}>{energies.secondaryEnergy.note || 'day of the month'}</div>
        </div>
      </div>

      <div style={combined}>
        <span style={label}>Combined</span>
        <span style={combinedValue}>{energies.combinedKey}</span>
      </div>

      <div style={cyclesGrid}>
        <div style={cycleCell(false)}>
          <div style={cycleLabel}>Universal Year</div>
          <div style={cycleValue(false)}>{cycles.universalYear.displayValue}</div>
          <div style={cycleNote}>{cycles.universalYear.dateLabel}</div>
        </div>
        <div style={cycleCell(false)}>
          <div style={cycleLabel}>Universal Month</div>
          <div style={cycleValue(false)}>{cycles.universalMonth.displayValue}</div>
          <div style={cycleNote}>{cycles.universalMonth.dateLabel}</div>
        </div>
        <div style={cycleCell(true)}>
          <div style={cycleLabel}>Personal Year</div>
          <div style={cycleValue(true)}>{cycles.personalYear ? cycles.personalYear.displayValue : '—'}</div>
          <div style={cycleNote}>{cycles.personalYear ? cycles.personalYear.dateLabel : 'Set birthday'}</div>
        </div>
        <div style={cycleCell(true)}>
          <div style={cycleLabel}>Personal Month</div>
          <div style={cycleValue(true)}>{cycles.personalMonth ? cycles.personalMonth.displayValue : '—'}</div>
          <div style={cycleNote}>{cycles.personalMonth ? cycles.personalMonth.dateLabel : 'Set birthday'}</div>
        </div>
      </div>

      {showRoster ? null : (
      <div style={birthdayRow}>
        <span style={label}>Birthday</span>
        {editing ? (
          <div style={birthdayEditor}>
            <input
              type="text"
              placeholder="YYYY-MM-DD"
              value={draft}
              autoFocus
              aria-label="Birthday in YYYY-MM-DD format"
              onChange={(event) => dispatch({ type: 'BIRTHDAY_DRAFT', value: event.target.value })}
              onKeyDown={(event) => {
                if (event.key === 'Enter') {
                  dispatch({ type: 'BIRTHDAY_SAVE', value: event.target.value });
                } else if (event.key === 'Escape') {
                  dispatch({ type: 'BIRTHDAY_CANCEL' });
                }
              }}
              style={birthdayInput}
            />
            <button
              type="button"
              style={smallButton}
              onClick={() => dispatch({ type: 'BIRTHDAY_SAVE', value: draft })}
            >
              Save
            </button>
            <button
              type="button"
              style={smallButton}
              onClick={() => dispatch({ type: 'BIRTHDAY_CANCEL' })}
            >
              Cancel
            </button>
          </div>
        ) : (
          <div style={birthdayEditor}>
            <span style={birthdayValue}>{birthday ? formatBirthday(birthday) : 'Not set'}</span>
            <button
              type="button"
              style={smallButton}
              onClick={() => dispatch({ type: 'BIRTHDAY_EDIT' })}
            >
              {birthday ? 'Edit' : 'Set'}
            </button>
          </div>
        )}
      </div>
      )}
      {birthdayError ? <div style={formError}>{birthdayError}</div> : null}

      <div style={calendar}>
        <div style={calendarHeader}>
          <span style={label}>Energy Calendar</span>
          <div style={calendarNav}>
            <button
              type="button"
              style={calendarArrow}
              aria-label="Previous month"
              title="Previous month"
              onClick={() => dispatch({ type: 'CALENDAR_SHIFT', delta: -1 })}
            >
              ‹
            </button>
            <span style={calendarMonthText}>{month.monthLabel}</span>
            <button
              type="button"
              style={calendarArrow}
              aria-label="Next month"
              title="Next month"
              onClick={() => dispatch({ type: 'CALENDAR_SHIFT', delta: 1 })}
            >
              ›
            </button>
            {isCurrentMonth ? null : (
              <button
                type="button"
                style={calendarTodayButton}
                title="Back to the current month"
                onClick={() => dispatch({ type: 'CALENDAR_TODAY' })}
              >
                Today
              </button>
            )}
          </div>
        </div>

        <div style={weekdayRow}>
          {weekdayNames.map((name) => (
            <div key={name} style={weekdayLabel}>{name}</div>
          ))}
        </div>

        {month.weeks.map((week, weekIndex) => (
          <div key={`week-${weekIndex}`} style={weekRow}>
            {week.map((cell, cellIndex) => {
              if (!cell.schedule || !cell.date) {
                return <div key={`blank-${weekIndex}-${cellIndex}`} style={calendarBlank} />;
              }

              const day = cell.schedule;
              return (
                <div key={cell.date} style={dayCell(cell.date === todayKey)}>
                  <div style={dayNumber}>{cell.dayNumber}</div>
                  <div style={dayPrimary}>{day.fullDateEnergy}</div>
                  <div style={daySecondary}>{day.secondaryEnergy}</div>
                </div>
              );
            })}
          </div>
        ))}
      </div>

      <div style={footer}>
        <span>GG33</span>
      </div>
    </div>
  );
};
